final_data = []
for i, row in enumerate(data, start=1):
    domain, quality, tc_type, diff, search_type, question, expected_result, caution = row
    tc_id = f"TC_{i:03d}_{domain.replace(' ', '')[:4]}_{tc_type}_{diff}"
    final_data.append({
        "ID": tc_id,
        "도메인": domain,
        "품질지표": quality,
        "테스트 케이스 유형": tc_type,
        "난이도": diff,
        "검색 형태": search_type,
        "질문": question,
        "기대 결과": expected_result,
        "답변 주의 요소": caution
    })

df = pd.DataFrame(final_data)
output_path = "QA_TestCases_MultiDomain.xlsx"
df.to_excel(output_path, index=False)
print(f"Excel file created: {output_path}")
